 * austeris - orchid #C25BD9, the colour of its mark (au).
 *
 * Import after the theme. Everything else - the hover shade, the soft fill,
 * the focus ring, the colour of text on an accent fill, and the trace of the
 * hue the greys carry - is derived from this one value.
 */
:root {
  --accent-base: #C25BD9;
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Badge.
 *
 * A small piece of state attached to something else: a count, a status, a
 * label. It is not a button and never was - if it can be clicked it is a Chip.
 *
 * Status colour is emphasis, never the message. A badge that means "failed"
 * says so in words as well, because colour alone is invisible to a reader who
 * does not separate red from green, and to anyone printing the screen.
 */
export const badgeVariants = cva(
  'inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs whitespace-nowrap',
  {
    variants: {
      variant: {
        outline: 'border border-line text-dim',
        soft: 'bg-soft font-medium text-dim',
        accent: 'bg-accent-soft font-medium text-accent',
        good: 'bg-good-soft font-medium text-good',
        warn: 'bg-warn-soft font-medium text-warn',
        bad: 'bg-bad-soft font-medium text-bad',
        info: 'bg-info-soft font-medium text-info',
      },
    },
    defaultVariants: { variant: 'outline' },
  },
)

export interface BadgeProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof badgeVariants> {}

export function Badge({ variant, className, ...props }: BadgeProps) {
  return <span className={cn(badgeVariants({ variant }), className)} {...props} />
}

import type { ButtonHTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { useRender } from '@base-ui/react/use-render'
// `cn` comes from the package rather than being copied in beside the
// component (ADR 0002): a helper every primitive shares should update
// centrally, and a project installing a component already has the package for
// the theme. shadcn's own components import it from `@/lib/utils`; that is a
// per-project alias, and a copied file cannot know what it points at.
import { cn } from 'dowel-ui'

/*
 * Button.
 *
 * Five variants, because that is what the line's products actually reach for:
 * one primary action per screen, a quiet default, a soft accent for something
 * selected, a destructive one, and an icon-only.
 *
 * Every colour and every size is a token. There are no `dark:` utilities and
 * no raw values - the theme swaps underneath, so the same class list is
 * correct in both themes and in every product's accent.
 */
export const buttonVariants = cva(
  [
    'inline-flex cursor-pointer items-center justify-center gap-1.5 whitespace-nowrap',
    'font-medium transition-colors',
    // Disabled is a state, not a colour: the button keeps its own hue and
    // loses contact instead, which reads the same whatever the accent is.
    'disabled:pointer-events-none disabled:opacity-50',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: 'rounded-md bg-accent font-semibold text-on-accent hover:bg-accent-2',
        ghost: 'rounded-md border border-line text-dim hover:border-line-2 hover:text-text',
        soft: 'rounded-md bg-accent-soft text-accent hover:bg-accent-soft/60',
        danger: 'rounded-md text-bad hover:bg-bad-soft',
        icon: 'rounded-md text-dim hover:bg-soft hover:text-text',
      },
      size: {
        sm: 'h-7 px-2.5 text-xs',
        md: 'h-9 px-3.5 text-sm',
        'icon-sm': 'size-7 [&_svg]:size-3.5',
        'icon-md': 'size-8 [&_svg]:size-4',
      },
    },
    defaultVariants: { variant: 'ghost', size: 'md' },
  },
)

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /**
   * Render something else with the button's clothes on - a link, most often.
   *
   * Takes the element itself rather than a boolean: `render={<a href="…" />}`.
   * A function is also accepted, for the rare case that needs the props
   * before deciding what to build with them.
   */
  render?: useRender.RenderProp
}

export function Button({ variant, size, render, className, type, ...props }: ButtonProps) {
  return useRender({
    render,
    defaultTagName: 'button',
    props: {
      // A `<button>` inside a form submits it unless told otherwise, which
      // surprises everyone once. When rendering as something else the
      // attribute is meaningless and would land on an `<a>`, so it is only
      // set for the element that has it - `render` is what says which.
      ...(render === undefined && type === undefined ? { type: 'button' } : { type }),
      className: cn(buttonVariants({ variant, size }), className),
      ...props,
    },
  })
}

import type { HTMLAttributes, MouseEvent } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Chip.
 *
 * A badge you can act on: a filter that can be removed, a tag with a count, a
 * selected value in a field. The difference from a Badge is entirely about
 * whether something happens when you click it - and if something does, that
 * part is a real `<button>` with a real label, not a decorative cross.
 *
 * `onRemove` is the reason this exists separately. Every product wrote the
 * same removable tag and every one of them made the cross a `<span>`, which
 * the keyboard cannot reach and a screen reader does not announce.
 */
export const chipVariants = cva(
  'inline-flex items-center gap-1 rounded-full border py-0.5 pl-2.5 text-xs whitespace-nowrap transition-colors',
  {
    variants: {
      variant: {
        outline: 'border-line text-dim',
        accent: 'border-transparent bg-accent-soft text-accent',
        soft: 'border-transparent bg-soft text-dim',
      },
      /** Padding on the right depends on whether a remove button sits there. */
      removable: {
        true: 'pr-1',
        false: 'pr-2.5',
      },
    },
    defaultVariants: { variant: 'outline', removable: false },
  },
)

export interface ChipProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, 'onSelect'>,
    Omit<VariantProps<typeof chipVariants>, 'removable'> {
  /** Shown after the label, for a count. */
  count?: number
}

/*
 * Removable, or not - and if removable, named.
 *
 * The two props travel together as a union rather than as two optionals, so
 * the type says what the component means: a remove button exists only when
 * there is a word for it. There is no default word on purpose. A string the
 * component invents is a string the product cannot translate, and it would
 * ship in English to every reader who does not read English.
 */
type Removable =
  | { onRemove: () => void; removeLabel: string }
  | { onRemove?: never; removeLabel?: never }

export function Chip({
  variant,
  count,
  onRemove,
  removeLabel,
  className,
  children,
  ...props
}: ChipProps & Removable) {
  return (
    <span className={cn(chipVariants({ variant, removable: Boolean(onRemove) }), className)} {...props}>
      {children}

      {count !== undefined && <span className="text-faint tabular-nums">{count}</span>}

      {onRemove && (
        <button
          type="button"
          aria-label={removeLabel}
          onClick={(event: MouseEvent<HTMLButtonElement>) => {
            // A chip is often inside something else that is also clickable.
            event.stopPropagation()
            onRemove()
          }}
          className={cn(
            'grid size-4 place-items-center rounded-full text-faint transition-colors',
            'hover:bg-line hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
            <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </span>
  )
}

import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { selectItemVariants, selectPopupVariants } from './select'

/*
 * Combobox.
 *
 * A Select you can type in. The list narrows as the query is typed, which is
 * the only difference that matters and the reason to reach for this one: a
 * Select stops being usable somewhere around thirty options, and a country
 * picker or a tag field is well past that.
 *
 * Everything the Select comment says about the native element applies here
 * too - there is no `<select>` under it, and the input is a real `<input
 * role="combobox">` so autofill, spellcheck and the phone keyboard still
 * work.
 *
 * Filtering is Base UI's: give the root an `items` array and it matches the
 * query against them with `Intl.Collator`, so accents and case behave the way
 * a reader in that language expects rather than the way `toLowerCase` does.
 * `filter` replaces the comparison; `filter={null}` turns it off for a list
 * that is filtered on a server.
 *
 * The chips are Base UI's too - Chips, Chip, ChipRemove - and that is worth
 * saying because inventing them is the obvious move and it goes wrong in one
 * specific way: hand-made chips end up as `<div>`s with an X that only a
 * pointer can reach, and the multi-select becomes keyboard-inaccessible at
 * exactly the point where it holds the most state. Base UI's are focusable,
 * walk with the arrows, and delete with Backspace.
 *
 * `Empty` renders only when nothing matched, and announces itself politely.
 * Its element stays mounted for that announcement to work, so it must not be
 * hidden with `display: none` or removed conditionally - which is why it is a
 * component here rather than a `{items.length === 0 && …}` in the product.
 */

export const comboboxInputVariants = cva([fieldClasses], {
  variants: {
    size: {
      sm: 'h-8 text-xs',
      md: 'h-9',
      lg: 'h-10 text-base',
    },
  },
  defaultVariants: { size: 'md' },
})

/** The list, and a row in it, are Select's - imported rather than copied.
 *
 * The two popups are the same object seen twice: a dropdown of options, one
 * of which can be chosen. A reader who uses both on one screen should not be
 * able to tell which is which until they type. Two `cva` calls that started
 * identical do not stay that way - one gets the padding fix - and then the
 * form has two dropdowns that are almost the same. */
export const comboboxPopupVariants = selectPopupVariants
export const comboboxItemVariants = selectItemVariants

/** The root. `items` is what gets filtered; `multiple` turns the value into an
 * array and makes the chips meaningful. */
export const Combobox = Base.Root

/** The wrapper for an input with something beside it - a clear button, an
 * icon, the chips. */
export const ComboboxInputGroup = Base.InputGroup

/** The button that opens the list without typing, for a reader who wants to
 * see everything there is. */
export const ComboboxTrigger = Base.Trigger

/** The chevron. Decorative. */
export const ComboboxIcon = Base.Icon

/** A labelled group of rows. */
export const ComboboxGroup = Base.Group

/** The tick, drawn only on a chosen row. */
export const ComboboxItemIndicator = Base.ItemIndicator

/** A polite live region for the state of an asynchronous list. Stays mounted,
 * like `Empty`, so the announcement actually fires. */
export const ComboboxStatus = Base.Status

/** The container the chips sit in. Its children are plain nodes, not a render
 * function - the chosen values are mapped by `ComboboxValue` inside it. */
export const ComboboxChips = Base.Chips

/** The current value, as a render function of it. This is what turns a
 * `multiple` value into one chip per entry. */
export const ComboboxValue = Base.Value

/** `size` is taken from the native `<input size>` - a width in characters,
 * which nothing here wants - and given to the variant instead. */
export interface ComboboxInputProps
  extends Omit<Base.Input.Props, 'size'>,
    VariantProps<typeof comboboxInputVariants> {}

/** Where the query is typed. A real `<input role="combobox">`. */
export function ComboboxInput({ size, className, ...props }: ComboboxInputProps) {
  return <Base.Input className={cn(comboboxInputVariants({ size }), className)} {...props} />
}

const iconButtonClasses = cn(
  'rounded-sm p-1 text-faint transition-colors hover:text-text',
  'focus-visible:outline-2 focus-visible:outline-accent',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
)

/** Empties the value. Base UI hides it while there is nothing to clear. */
export function ComboboxClear({ className, ...props }: Base.Clear.Props) {
  return <Base.Clear className={cn(iconButtonClasses, className)} {...props} />
}

export interface ComboboxPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof comboboxPopupVariants> {
  /** Preferred side of the input. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the input, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the input. */
export function ComboboxPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: ComboboxPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(comboboxPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The rows, as a list. Undressed: it is a wrapper, and the popup around it
 * already carries the border and the padding. */
export const ComboboxList = Base.List

/** A row. */
export function ComboboxItem({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(comboboxItemVariants(), className)} {...props} />
}

/** What is shown when nothing matched. The words are the product's. */
export function ComboboxEmpty({ className, ...props }: Base.Empty.Props) {
  return <Base.Empty className={cn('px-2 py-3 text-center text-sm text-faint', className)} {...props} />
}

/** One chosen value, in a multiple combobox. Focusable, so it can be reached
 * and removed without a pointer. */
export function ComboboxChip({ className, ...props }: Base.Chip.Props) {
  return (
    <Base.Chip
      className={cn(
        'flex items-center gap-1 rounded-sm bg-soft px-1.5 py-0.5 text-xs text-text',
        'outline-none data-[highlighted]:bg-accent-soft data-[highlighted]:text-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The X on a chip. A real button, which is what makes Backspace and Enter
 * both work on it. */
export function ComboboxChipRemove({ className, ...props }: Base.ChipRemove.Props) {
  return <Base.ChipRemove className={cn(iconButtonClasses, 'p-0', className)} {...props} />
}

/** The caption above a group. */
export function ComboboxGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import type { ReactNode } from 'react'
import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { comboboxItemVariants } from './combobox'
import { Kbd } from './kbd'

/*
 * CommandPalette.
 *
 * One box that finds anything: the shortcut opens it, typing narrows a list,
 * Enter runs what is highlighted.
 *
 * It is a Combobox rather than a Dialog with a field in it, and that is Base
 * UI's own arrangement rather than a shortcut taken here: put the input
 * *inside* the popup and the popup becomes `role="dialog"` on its own, with
 * the input still announced as the combobox that owns the list. The filtering,
 * the highlight, the arrow keys and the type-ahead are the ones Combobox
 * already has - there is no second implementation of any of it.
 *
 * What is left for the product is everything that makes a palette that
 * product's: what the items are, how they are grouped, what running one does.
 * `items` is deliberately `unknown[]` - a palette lists commands, works,
 * settings and recent files in the same box, and a type that admitted only
 * strings would push every product into the same stringly-typed workaround.
 */

export const commandPalettePopupVariants = cva(
  [
    'flex w-[min(36rem,calc(100vw-2rem))] flex-col overflow-hidden',
    'rounded-xl border border-line bg-raise text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        md: 'max-h-[24rem]',
        lg: 'max-h-[32rem]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled by `open`/`onOpenChange`, because what opens a palette
 * is a shortcut somewhere else in the application. */
export const CommandPalette = Base.Root

/** A row. The same clothes as a Combobox row, on purpose: a palette is a list
 * of choices, and two lists of choices in one product should not differ. */
export const CommandPaletteItem = Base.Item

/** The list. Takes a render function over the filtered items. */
export const CommandPaletteList = Base.List

/** Shown when nothing matches. The words are the product's. */
export const CommandPaletteEmpty = Base.Empty

/** A labelled group, for a palette that lists more than one kind of thing. */
export const CommandPaletteGroup = Base.Group

export interface CommandPalettePopupProps
  extends Omit<Base.Popup.Props, 'aria-label'>,
    VariantProps<typeof commandPalettePopupVariants> {
  /**
   * What the palette is called, for a screen reader. Required, and required
   * for a reason particular to this component: the popup is a dialog, and a
   * dialog is named by its own visible title - which a palette does not have,
   * because the field is the first thing in it.
   *
   * So the name has to come from outside, it has to be the product's word, and
   * nothing else can supply it. A palette without one is announced as "dialog"
   * and nothing more; making the prop required is what stops that shipping.
   */
  'aria-label': string
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The palette itself: a dim over the page, and the box in the upper third of
 * it - where the eye already is, rather than dead centre. */
export function CommandPalettePopup({
  size,
  container,
  className,
  children,
  ...props
}: CommandPalettePopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Backdrop
        className={cn(
          'fixed inset-0 bg-black/55 backdrop-blur-[2px]',
          '[z-index:var(--z-overlay)]',
          '[transition:opacity_var(--duration-quick)_var(--ease-out)]',
          'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        )}
      />
      <Base.Positioner
        className="[z-index:var(--z-palette)]"
        // Anchored to the viewport rather than to a trigger: a palette has no
        // trigger to point at, and the one it does have is a keystroke.
        positionMethod="fixed"
        side="bottom"
        align="center"
        sideOffset={0}
        alignOffset={0}
      >
        <Base.Popup
          className={cn(commandPalettePopupVariants({ size }), className)}
          {...props}
        >
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface CommandPaletteInputProps extends Base.Input.Props {
  /** Shown at the right of the field, as `['Esc']`. Decorative. */
  hint?: string[]
}

/** The field. Sits inside the popup, which is what makes the popup a dialog
 * and the field its combobox. */
export function CommandPaletteInput({ hint, className, ...props }: CommandPaletteInputProps) {
  return (
    <div className="flex items-center gap-2 border-b border-line px-3">
      <MagnifierIcon />
      <Base.Input
        className={cn(
          'h-11 w-full bg-transparent text-sm text-text placeholder:text-faint',
          'focus-visible:outline-none',
          className,
        )}
        {...props}
      />
      {hint && <Kbd keys={hint} aria-hidden className="shrink-0" />}
    </div>
  )
}

/** The row's own layout: an icon, what it is, and where it lives. */
export function CommandPaletteRow({
  icon,
  hint,
  className,
  children,
  ...props
}: {
  icon?: ReactNode
  hint?: ReactNode
  className?: string
  children: ReactNode
} & Omit<React.HTMLAttributes<HTMLDivElement>, 'children'>) {
  return (
    <div className={cn('flex w-full items-center gap-2.5', className)} {...props}>
      {icon}
      <span className="min-w-0 flex-1 truncate">{children}</span>
      {hint !== undefined && <span className="shrink-0 text-2xs text-faint">{hint}</span>}
    </div>
  )
}

export { comboboxItemVariants as commandPaletteItemVariants }

function MagnifierIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width="15"
      height="15"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      aria-hidden
      className="shrink-0 text-faint"
    >
      <circle cx="7" cy="7" r="4.5" />
      <path d="M10.5 10.5L14 14" strokeLinecap="round" />
    </svg>
  )
}

import { AlertDialog as Base } from '@base-ui/react/alert-dialog'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * ConfirmDialog.
 *
 * The dialog for a choice that cannot be taken back - deleting, discarding,
 * revoking. It looks almost exactly like Dialog, and that is deliberate: the
 * difference is not clothes, it is what the popup is allowed to do.
 *
 * A Dialog is dismissed by clicking away, because a Dialog is a place the user
 * wandered into. This one is not: Base UI's `AlertDialog` announces itself as
 * `role="alertdialog"`, which tells a screen reader the popup is interrupting
 * rather than presenting, and it forces `modal` and `disablePointerDismissal`
 * on - `AlertDialog.Root` omits both from Dialog's props, so there is nothing
 * to turn off. A press outside does nothing at all.
 *
 * `Escape` still closes it, and that is deliberate rather than an oversight: a
 * popup with no keyboard way out is a trap. The difference is between a
 * deliberate keypress and clicking absentmindedly beside a dialog.
 *
 * So the rule for choosing between the two is not how important the content
 * feels. It is whether dismissing it by a stray click would be a loss.
 */

export const confirmDialogPopupVariants = cva(
  [
    'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
    'rounded-xl border border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(22rem,calc(100vw-2rem))]',
        md: 'w-[min(26rem,calc(100vw-2rem))]',
        lg: 'w-[min(34rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `ConfirmDialogTrigger`. */
export const ConfirmDialog = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const ConfirmDialogTrigger = Base.Trigger

/** What closes it - and the only thing that does, which is why a confirm
 * dialog with no `ConfirmDialogClose` inside it is a trap. */
export const ConfirmDialogClose = Base.Close

/** The scrim. Darker than the Dialog's, because what is behind it is not just
 * out of reach for a moment - it is waiting on an answer. */
export function ConfirmDialogBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/60 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface ConfirmDialogPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof confirmDialogPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The dialog itself, announced as `alertdialog`. Portalled, so it is not
 * clipped by whatever it was opened from. */
export function ConfirmDialogPopup({
  size,
  container,
  backdrop = true,
  className,
  children,
  ...props
}: ConfirmDialogPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <ConfirmDialogBackdrop />}
      <Base.Popup
        className={cn(
          confirmDialogPopupVariants({ size }),
          '[z-index:var(--z-modal)]',
          className,
        )}
        {...props}
      >
        {children}
      </Base.Popup>
    </Base.Portal>
  )
}

/** The question. Base UI points the popup's `aria-labelledby` at it, so this
 * is what a screen reader reads out when the dialog interrupts. */
export function ConfirmDialogTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** What the answer costs, and the popup's `aria-describedby`. On this dialog
 * it is close to required: the title asks, the description says what happens. */
export function ConfirmDialogDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the two answers go. Right-aligned, because the choice belongs where
 * the eye leaves the sentence. */
export function ConfirmDialogActions({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-5 flex justify-end gap-2', className)} {...props} />
}

import { ContextMenu as Base } from '@base-ui/react/context-menu'
import { menuItemVariants, menuPopupVariants } from './menu'
import { cn } from 'dowel-ui'

/*
 * ContextMenu.
 *
 * The same list of actions as Menu, opened the other way round: by right
 * click, or by a long press on a touch screen, over an *area* rather than
 * from a button. So the trigger is not a control - it is the region the menu
 * belongs to, a row, a canvas, a file tile - and it renders a `<div>`.
 *
 * That difference is the whole component. Everything below the Root is Menu's
 * own: Base UI re-exports the Portal, Positioner, Popup, Item and the rest
 * from the menu package, so the popup that opens here is literally the same
 * popup, with the same keyboard, the same type-ahead and the same submenus.
 *
 * Which is why the clothes are imported rather than copied. Two `cva` calls
 * that started identical drift within a release - one gets a padding fix, the
 * other does not - and then a product has two menus that are almost the same,
 * which is worse than two that differ on purpose.
 *
 * What Base UI does *not* give this one is `openOnHover`, `modal` or a
 * `handle`: a context menu is opened by a gesture over an anchor point, not
 * by a trigger element it can be attached to from elsewhere.
 */

/** The root. It positions against the pointer, so there is nothing to anchor
 * and nothing to control but `onOpenChange`. */
export const ContextMenu = Base.Root

/** The area that opens it. A `<div>`, not a button: give it `render` to make
 * it the row or the canvas it belongs to rather than a wrapper. */
export const ContextMenuTrigger = Base.Trigger

/** A labelled group of items, for a menu long enough to need headings. */
export const ContextMenuGroup = Base.Group

/** A submenu, opened from a `ContextMenuSubTrigger` inside the parent. */
export const ContextMenuSub = Base.SubmenuRoot

export interface ContextMenuPopupProps extends Base.Popup.Props {
  /** How wide the popup starts. The same three as Menu's. */
  size?: 'sm' | 'md' | 'lg'
  /** Where to portal to. Defaults to the document body, which keeps the menu
   * from being clipped by the very row it was opened over. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled, and positioned against the point that was clicked
 * rather than against an element. */
export function ContextMenuPopup({
  size,
  container,
  className,
  children,
  ...props
}: ContextMenuPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner className="[z-index:var(--z-menu)]">
        <Base.Popup className={cn(menuPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface ContextMenuItemProps extends Base.Item.Props {
  /** `danger` draws the destructive one apart, in the colour of something
   * that cannot be undone. */
  tone?: 'default' | 'danger'
}

/** An action. */
export function ContextMenuItem({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.Item className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that opens a submenu. Drawn like any other, because it is one. */
export function ContextMenuSubTrigger({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.SubmenuTrigger className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that carries a tick. The state is the caller's. */
export function ContextMenuCheckboxItem({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.CheckboxItem className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** The tick itself, drawn only when the item is checked. */
export const ContextMenuCheckboxIndicator = Base.CheckboxItemIndicator

/** A line between groups of items. Decorative, and marked as such. */
export function ContextMenuSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

/** The caption above a group. */
export function ContextMenuGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import { useCallback, useEffect, useRef, useState, type HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Copyable.
 *
 * Any text that someone will eventually want to copy - an id, a path, a hash,
 * a token - copied with one click. The rule comes from nitid: if a value is
 * worth showing, it is worth being able to take away, and selecting a
 * monospaced id by hand is a small daily tax.
 *
 * Two things this gets right that the hand-written version usually does not.
 * It is a `<button>`, so the keyboard can reach it and a screen reader says
 * what it does. And the confirmation is announced, not only drawn: a tick that
 * appears silently tells a sighted user it worked and tells nobody else.
 *
 * The clipboard can refuse - it needs a secure context and, in some browsers,
 * a permission. A refusal is reported rather than swallowed, because a button
 * that looks like it worked and did not is worse than one that says it failed.
 */
export interface CopyableProps extends Omit<HTMLAttributes<HTMLButtonElement>, 'onCopy'> {
  /** What lands on the clipboard. Defaults to the visible text. */
  value?: string
  /** The visible text. */
  children: string
  /** What the button is called, for a screen reader. Required, and
   * deliberately without a default: a string the component invents is a
   * string the product cannot translate, and it would ship in English to
   * every reader who does not read English. */
  label: string
  /** What is announced after a successful copy. Required for the same
   * reason. */
  copiedLabel: string
  /** Told what happened, for a product that wants its own toast. */
  onCopy?: (ok: boolean) => void
}

export function Copyable({
  value,
  children,
  label,
  copiedLabel,
  onCopy,
  className,
  ...props
}: CopyableProps) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)

  // A component that sets state on a timer has to stop when it goes away, or
  // it wakes up in a tree that no longer exists.
  useEffect(() => () => clearTimeout(timer.current), [])

  const copy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value ?? children)
      setCopied(true)
      onCopy?.(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 1600)
    } catch {
      // No secure context, or permission refused. Say so rather than pretend.
      onCopy?.(false)
    }
  }, [value, children, onCopy])

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={copied ? copiedLabel : label}
      className={cn(
        'group inline-flex max-w-full items-center gap-1.5 rounded-sm px-1 py-0.5 text-left',
        'font-mono text-xs text-dim transition-colors',
        'hover:bg-soft hover:text-text',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        className,
      )}
      {...props}
    >
      <span className="truncate">{children}</span>

      <span className={cn('shrink-0 transition-colors', copied ? 'text-good' : 'text-faint')} aria-hidden>
        {copied ? <Tick /> : <Clipboard />}
      </span>

      {/* Drawn confirmation is invisible to a screen reader; this is the part
          that actually says it worked. */}
      <span role="status" aria-live="polite" className="sr-only">
        {copied ? copiedLabel : ''}
      </span>
    </button>
  )
}

function Clipboard() {
  return (
    <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden>
      <rect x="5.5" y="2.5" width="8" height="10" rx="1.5" />
      <path d="M10.5 2.5v-.5a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h.5" />
    </svg>
  )
}

function Tick() {
  return (
    <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M3 8.5l3.5 3.5L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

import { Dialog as Base } from '@base-ui/react/dialog'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Dialog.
 *
 * The parts are exposed rather than wrapped in one component with `title` and
 * `footer` props. The products that did it the other way ended up passing
 * `footer={<>…</>}` within a week, which is a slot with extra steps - and a
 * dialog that owns its own close button owns a word for it, which is a word
 * the product cannot translate.
 *
 * Behaviour is Base UI's: the focus trap, the return of focus to whatever
 * opened it, `Escape`, the scroll lock, and the `aria-labelledby` that ties
 * the popup to its own title. None of that is worth rewriting, and all of it
 * is wrong in the ways nobody notices until someone is navigating by keyboard.
 *
 * What is ours is the clothes, and the enter and leave: the popup arrives with
 * `data-open` and leaves with `data-closed`, both of which Base UI sets, so
 * the animation is a class list rather than a state machine.
 */

export const dialogPopupVariants = cva(
  [
    'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
    'rounded-xl border border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(24rem,calc(100vw-2rem))]',
        md: 'w-[min(28rem,calc(100vw-2rem))]',
        lg: 'w-[min(40rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `Dialog.Trigger`. */
export const Dialog = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const DialogTrigger = Base.Trigger

/** What closes it - the same, for a cancel button or an X. */
export const DialogClose = Base.Close

/** The scrim. Dark because a modal is a modal: what is behind it is out of
 * reach, and saying so with contrast is the only thing that reads at a
 * glance. */
export function DialogBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/50 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface DialogPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof dialogPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by whatever it was opened from. Pass an
   * element to put it somewhere else - inside a dialog that is already open,
   * or into a container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The dialog itself. Portalled, so it is not clipped by whatever it was
 * opened from. */
export function DialogPopup({
  size,
  container,
  backdrop = true,
  className,
  children,
  ...props
}: DialogPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <DialogBackdrop />}
      <Base.Popup
        className={cn(dialogPopupVariants({ size }), '[z-index:var(--z-modal)]', className)}
        {...props}
      >
        {children}
      </Base.Popup>
    </Base.Portal>
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * dialog with one is named for a screen reader without anyone arranging it. */
export function DialogTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function DialogDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the actions go. Right-aligned, because the primary action of a
 * dialog belongs where the eye leaves the sentence. */
export function DialogActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-5 flex justify-end gap-2', className)} {...props} />
}

import { Drawer as Base } from '@base-ui/react/drawer'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Drawer.
 *
 * A panel that slides in from an edge and holds the screen while it is there -
 * a filter sheet, a detail pane, a form too long to centre. Modal like Dialog,
 * placed like nothing else.
 *
 * Base UI positions none of it. Unlike Popover there is no Positioner and no
 * anchor to measure against; the edge it comes from is entirely CSS, which is
 * what the `side` variant is. It drives three things at once and they have to
 * agree: where the Viewport pushes the panel, which border it grows against,
 * and which way it is translated while opening and closing.
 *
 * `swipeDirection` is the other half and cannot be inferred here: it lives on
 * the root, while `side` lives on the popup, so the two are set together by
 * hand - `side="right"` with `swipeDirection="right"`, `side="bottom"` with
 * `down`, which is Base UI's default. Left unmatched, the drawer slides in
 * from one edge and is flicked away towards another.
 *
 * The transitions key off `data-starting-style` and `data-ending-style` rather
 * than `data-closed`. That is Base UI's own convention for the drawer, and the
 * reason is that a drawer is dragged as well as animated: the popup carries a
 * live `--drawer-swipe-movement-*` while a finger is on it, and the transform
 * has to compose with that rather than replace it.
 */

/** The Viewport: fixed to the whole window, pushing the popup to one edge.
 *
 * It is separate from the popup because a drawer that is its own positioner
 * cannot be scrolled independently of where it sits - and the panel needs to
 * scroll while the edge it is pinned to does not move. */
const drawerViewportVariants = cva('fixed inset-0 flex', {
  variants: {
    side: {
      right: 'justify-end',
      left: 'justify-start',
      bottom: 'items-end',
    },
  },
  defaultVariants: { side: 'right' },
})

export const drawerPopupVariants = cva(
  [
    'flex flex-col overflow-y-auto overscroll-contain',
    'border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // Composed with the live swipe offset rather than replacing it, so a
    // half-dragged drawer animates from where the finger left it.
    '[transition:transform_var(--duration-base)_var(--ease-out)]',
    'will-change-transform',
  ],
  {
    variants: {
      /* Where it comes from. The three the products of the line reach for:
       * a right-hand pane, its mirror, and a bottom sheet. */
      side: {
        right: [
          'h-full w-[min(24rem,calc(100vw-3rem))] border-l',
          '[transform:translateX(var(--drawer-swipe-movement-x))]',
          'data-[starting-style]:[transform:translateX(100%)]',
          'data-[ending-style]:[transform:translateX(100%)]',
        ],
        left: [
          'h-full w-[min(24rem,calc(100vw-3rem))] border-r',
          '[transform:translateX(var(--drawer-swipe-movement-x))]',
          'data-[starting-style]:[transform:translateX(-100%)]',
          'data-[ending-style]:[transform:translateX(-100%)]',
        ],
        bottom: [
          'max-h-[80vh] w-full rounded-t-xl border-t',
          '[transform:translateY(var(--drawer-swipe-movement-y))]',
          'data-[starting-style]:[transform:translateY(100%)]',
          'data-[ending-style]:[transform:translateY(100%)]',
        ],
      },
    },
    defaultVariants: { side: 'right' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `DrawerTrigger`. */
export const Drawer = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const DrawerTrigger = Base.Trigger

/** What closes it - the same, for a cancel button or an X. */
export const DrawerClose = Base.Close

/** The scrim. Dark because a drawer is modal: what is behind it is out of
 * reach, and saying so with contrast is the only thing that reads at a
 * glance. */
export function DrawerBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/50 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface DrawerPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof drawerPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The panel. Portalled, and wrapped in its own viewport so the edge it is
 * pinned to holds still while the contents scroll. */
export function DrawerPopup({
  container,
  backdrop = true,
  side,
  className,
  children,
  ...props
}: DrawerPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <DrawerBackdrop />}
      <div className={cn(drawerViewportVariants({ side }), '[z-index:var(--z-modal)]')}>
        <Base.Viewport className="flex w-full">
          <Base.Popup
            className={cn(drawerPopupVariants({ side }), className)}
            {...props}
          >
            {children}
          </Base.Popup>
        </Base.Viewport>
      </div>
    </Base.Portal>
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * drawer with one is named for a screen reader without anyone arranging it. */
export function DrawerTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function DrawerDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the actions go. Pushed to the bottom of the panel rather than sitting
 * under the content, because a drawer is tall and its buttons should not
 * wander up the page when there is little in it. */
export function DrawerActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-auto flex justify-end gap-2 pt-5', className)} {...props} />
}

import type { InputHTMLAttributes, Ref } from 'react'
import { cn } from 'dowel-ui'

/*
 * Input.
 *
 * A single-line field. It is a plain `<input>` with the line's clothes on, so
 * everything a browser gives an input for free - autofill, spellcheck, the
 * right keyboard on a phone, `type="email"` validation - still works.
 *
 * The focus ring is the accent, drawn outside the border rather than replacing
 * it: a field that only changes colour on focus is invisible to anyone who
 * cannot distinguish those two colours.
 */
export const fieldClasses = cn(
  'w-full rounded-md border border-line bg-transparent px-2.5 py-1.5',
  'text-sm text-text placeholder:text-faint',
  'transition-colors hover:border-line-2',
  'focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-accent',
  // A field nobody can type in should look like one.
  'disabled:cursor-not-allowed disabled:opacity-50',
  // `aria-invalid` rather than a prop: the attribute is what a screen reader
  // reads, so making it the source of the colour keeps the two in step.
  'aria-invalid:border-bad aria-invalid:focus-visible:outline-bad',
)

export interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  /** React 19 passes `ref` as a plain prop; it is declared so callers can
   * reach the element to focus it or read its selection. */
  ref?: Ref<HTMLInputElement>
}

export function Input({ className, ref, ...props }: InputProps) {
  return <input ref={ref} className={cn(fieldClasses, 'h-9', className)} {...props} />
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Kbd.
 *
 * A key, as printed in a menu or a hint: `Ctrl` `K`. It is a `<kbd>` element
 * because that is what the element is for - a screen reader announces it as
 * keyboard input rather than reading a stray capital letter.
 *
 * The platform substitution is the useful part. A shortcut written `Ctrl+K` is
 * wrong on a Mac, where the same shortcut is `⌘K`, and every product either
 * hard-codes one of them or writes the branch again.
 */

/** Whether this machine writes shortcuts the Apple way. */
function isApplePlatform(): boolean {
  if (typeof navigator === 'undefined') return false
  return /mac|iphone|ipad|ipod/i.test(navigator.platform || navigator.userAgent)
}

/** What a key is called here. `Mod` is the one that differs: command on Apple
 * platforms, control everywhere else. */
export function keyLabel(key: string, apple: boolean = isApplePlatform()): string {
  const shared: Record<string, string> = {
    Enter: '↵',
    Escape: 'Esc',
    ArrowUp: '↑',
    ArrowDown: '↓',
    ArrowLeft: '←',
    ArrowRight: '→',
    Backspace: '⌫',
    Tab: '⇥',
    Space: '␣',
  }
  const perPlatform: Record<string, [apple: string, other: string]> = {
    Mod: ['⌘', 'Ctrl'],
    Alt: ['⌥', 'Alt'],
    Shift: ['⇧', 'Shift'],
  }

  const platform = perPlatform[key]
  if (platform) return apple ? platform[0] : platform[1]
  return shared[key] ?? key
}

export interface KbdProps extends HTMLAttributes<HTMLElement> {
  /** Keys of a shortcut, in order: `['Mod', 'K']`. Given this, the component
   * writes the separators and the platform's own names. */
  keys?: string[]
}

export function Kbd({ keys, className, children, ...props }: KbdProps) {
  const cap = cn(
    'inline-flex min-w-5 items-center justify-center rounded-sm border border-line bg-soft',
    'px-1 py-0.5 font-mono text-2xs leading-none text-dim',
  )

  if (!keys) {
    return (
      <kbd className={cn(cap, className)} {...props}>
        {children}
      </kbd>
    )
  }

  return (
    <span className={cn('inline-flex items-center gap-0.5', className)} {...props}>
      {keys.map((key) => (
        <kbd key={key} className={cap}>
          {keyLabel(key)}
        </kbd>
      ))}
    </span>
  )
}

import { Menu as Base } from '@base-ui/react/menu'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Menu.
 *
 * A list of actions that opens from a button - the row menu, the overflow
 * menu, the one behind the three dots. The products all wrote this by hand,
 * and all of them wrote the same three hundred lines: a click-outside
 * listener, an Escape handler, and a `stopPropagation` on every item so that
 * choosing an action does not also open the row underneath.
 *
 * None of that is what makes a menu hard. What makes it hard is the keyboard:
 * arrows that wrap, Home and End, type-ahead that finds an item by its first
 * letters, a submenu that opens on the right key and closes when the pointer
 * leaves diagonally. Base UI has all of it.
 *
 * The items are exposed rather than taken as an array of `{ label, onSelect }`.
 * An array is enough until the first separator, the first checkbox item and
 * the first submenu - and each of those arrives as another field on the object
 * rather than as the JSX it obviously is.
 */

export const menuPopupVariants = cva(
  [
    'min-w-40 rounded-md border border-line bg-raise p-1 text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'min-w-32',
        md: 'min-w-40',
        lg: 'min-w-56',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** One row of the menu. `danger` draws the destructive one apart from the
 * rest - in the colour of something that cannot be undone. */
export const menuItemVariants = cva(
  [
    'flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm',
    'outline-none transition-colors',
    // Base UI marks the item under the pointer or the keyboard the same way,
    // so one rule covers both and they cannot disagree.
    'data-[highlighted]:bg-soft data-[highlighted]:text-text',
    'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
    '[&_svg]:size-3.5 [&_svg]:shrink-0',
  ],
  {
    variants: {
      tone: {
        default: 'text-dim data-[highlighted]:text-text',
        danger: 'text-bad data-[highlighted]:bg-bad-soft data-[highlighted]:text-bad',
      },
    },
    defaultVariants: { tone: 'default' },
  },
)

/** The root. Uncontrolled by default; `open` and `onOpenChange` make it
 * controlled. */
export const Menu = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const MenuTrigger = Base.Trigger

/** A labelled group of items, for a menu long enough to need headings. */
export const MenuGroup = Base.Group

/** A submenu, opened from a `MenuSubTrigger` inside the parent. */
export const MenuSub = Base.SubmenuRoot

export interface MenuPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof menuPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body, which keeps the menu
   * from being clipped by a row with `overflow: hidden` - which is where most
   * hand-written ones go to die. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled and positioned against the trigger. */
export function MenuPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: MenuPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(menuPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface MenuItemProps extends Base.Item.Props, VariantProps<typeof menuItemVariants> {}

/** An action. Closing the menu afterwards is Base UI's default, which is
 * almost always right - `closeOnClick={false}` is for the one that is not. */
export function MenuItem({ tone, className, ...props }: MenuItemProps) {
  return <Base.Item className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that opens a submenu. Drawn like any other, because it is one. */
export function MenuSubTrigger({ tone, className, ...props }: MenuItemProps) {
  return <Base.SubmenuTrigger className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that carries a tick. The state is the caller's - a menu does not
 * remember anything. */
export function MenuCheckboxItem({ tone, className, ...props }: MenuItemProps) {
  return <Base.CheckboxItem className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** The tick itself, drawn only when the item is checked. */
export const MenuCheckboxIndicator = Base.CheckboxItemIndicator

/** A line between groups of items. Decorative, and marked as such: a screen
 * reader announcing "separator" between every pair of actions is noise. */
export function MenuSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

/** The caption above a group. */
export function MenuGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Panel.
 *
 * The raised surface everything else sits on. It is the one place a screen
 * gets its structure from, so it stays deliberately plain: a ground, a
 * hairline, a corner.
 *
 * The two products it came from disagreed about that corner - one used 16px,
 * the other 12px, for the component with the same name and the same purpose.
 * It is `lg` here, and `SectionLabel` is included because a panel almost
 * always has one and every product wrote its own.
 */
export const panelVariants = cva('bg-raise', {
  variants: {
    variant: {
      /* The default: a surface that sits on the page. */
      raised: 'rounded-lg border border-line',
      /* For something that has left the page - a menu, a popover. The shadow
       * is what says how far away it is. */
      floating: 'rounded-lg border border-line shadow-raise',
      /* Inside another panel, where a second border would be a box in a box. */
      inset: 'rounded-inner bg-soft',
    },
  },
  defaultVariants: { variant: 'raised' },
})

export interface PanelProps
  extends HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof panelVariants> {}

export function Panel({ variant, className, ...props }: PanelProps) {
  return <div className={cn(panelVariants({ variant }), className)} {...props} />
}

/**
 * The small uppercase caption above a block of content.
 *
 * Its tracking is the one the products argued about - 0.08em in six files and
 * 0.09em in three - and it is a token now, so the argument cannot recur.
 */
export function SectionLabel({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        'flex items-center gap-2 text-2xs font-medium uppercase tracking-caption text-faint',
        className,
      )}
      {...props}
    />
  )
}

import { Popover as Base } from '@base-ui/react/popover'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Popover.
 *
 * A panel anchored to the thing that opened it, for content that belongs
 * beside a control rather than in the middle of the screen: a filter, a small
 * form, a menu of settings that is not a menu.
 *
 * Where Dialog is centred and covers the page, this one is placed, and the
 * placing is the part that is easy to get wrong. It goes through a Positioner
 * between the Portal and the Popup - Base UI measures the trigger, measures
 * the popup, and flips or shifts it when the preferred side does not fit. So
 * `side` and `align` are a preference, not an instruction, and a popover near
 * the bottom of the window will come out above its trigger. That is the
 * behaviour worth having; a popover that stays where it was told is a popover
 * half off the screen.
 *
 * `sideOffset` is a distance from the anchor and belongs to the Positioner,
 * not the Popup, so it is taken here and passed inward. The Arrow is optional
 * and sits inside the Popup, where Base UI rotates it to whichever side the
 * popup actually landed on.
 *
 * It is not modal. The page underneath stays live, and focus is not trapped -
 * which is right for a panel beside a control and wrong for a decision.
 */

export const popoverPopupVariants = cva(
  [
    'rounded-lg border border-line bg-raise p-4 text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.97] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0',
    // Grow out of the edge it is anchored to rather than out of its own
    // middle, so the motion points back at the trigger.
    'origin-[var(--transform-origin)]',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(16rem,calc(100vw-2rem))]',
        md: 'w-[min(20rem,calc(100vw-2rem))]',
        lg: 'w-[min(28rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `PopoverTrigger`. */
export const Popover = Base.Root

/** What opens it, and what the popup is measured against. */
export const PopoverTrigger = Base.Trigger

/** What closes it, for a button inside the panel. */
export const PopoverClose = Base.Close

export interface PopoverPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof popoverPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit,
   * and defaults it to the bottom. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. Base UI centres it by default. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Whether to draw the arrow pointing back at the trigger. */
  arrow?: boolean
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled and positioned, so it is not clipped by an ancestor
 * with `overflow: hidden` - which is where most anchored popups go to die.
 *
 * `side` and `align` are passed straight through rather than defaulted here:
 * Base UI's own defaults are already bottom and centre, and writing them out
 * again would be one more place for the two to disagree. */
export function PopoverPopup({
  size,
  side,
  align,
  sideOffset = 8,
  arrow = true,
  container,
  className,
  children,
  ...props
}: PopoverPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-floating)]"
      >
        <Base.Popup className={cn(popoverPopupVariants({ size }), className)} {...props}>
          {arrow ? <PopoverArrow /> : null}
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The notch pointing back at the trigger. Base UI rotates it to whatever side
 * the popup landed on, which is why the rotation is keyed off `data-side`
 * rather than off the `side` that was asked for. */
export function PopoverArrow({ className, ...props }: Base.Arrow.Props) {
  return (
    <Base.Arrow
      className={cn(
        'h-2 w-2 rotate-45 border border-line bg-raise',
        'data-[side=bottom]:-top-1 data-[side=bottom]:border-r-0 data-[side=bottom]:border-b-0',
        'data-[side=top]:-bottom-1 data-[side=top]:border-t-0 data-[side=top]:border-l-0',
        'data-[side=left]:-right-1 data-[side=left]:border-b-0 data-[side=left]:border-l-0',
        'data-[side=right]:-left-1 data-[side=right]:border-r-0 data-[side=right]:border-t-0',
        className,
      )}
      {...props}
    />
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * popover with one is named for a screen reader without anyone arranging it. */
export function PopoverTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-sm font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function PopoverDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

import { PreviewCard as Base } from '@base-ui/react/preview-card'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * PreviewCard.
 *
 * The card that appears when a link is hovered: who the author is, what the
 * issue says, what is behind the URL. Rich content - an avatar, a few lines,
 * a figure or two - rather than the phrase a Tooltip holds.
 *
 * Positioned the same way a Popover is, through a Positioner between the
 * Portal and the Popup, so it flips and shifts to stay on screen. What differs
 * is how it opens: hovering the trigger, after a delay, and it stays open
 * while the pointer travels from the link to the card. That last part is the
 * whole trick - a card that vanishes when the pointer leaves the link cannot
 * be read, let alone clicked into.
