    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.97] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0',
