import { useCallback, useRef, type InputHTMLAttributes, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Kbd } from './kbd'
import { useShortcut } from './shortcut'

/*
 * SearchField.
 *
 * An Input that knows it is a search box, which is three small things the
 * products kept not doing:
 *
 *   - a magnifier, so the field is recognisable before it is read;
 *   - a way to clear it that is not "select all and delete" - and one that a
 *     keyboard can reach, which a decorative `<span>` cannot;
 *   - the shortcut that focuses it, shown in the field rather than learned.
 *
 * `type="search"` is deliberate: it is what tells a browser to offer previous
 * queries, and what makes Escape clear the field on the platforms where that
 * is the convention. The browser's own clear button is hidden, because it is
 * drawn in the operating system's chrome and cannot be made to match - the
 * same reason the line does not use a native `<select>`.
 */

export interface SearchFieldProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'onChange'> {
  /** The query. Controlled, because a search box that owns its own text
   * cannot be cleared by the thing that owns the results. */
  value: string
  /** Told the new query on every keystroke. */
  onValueChange: (value: string) => void
  /**
   * What the clear button is called, for a screen reader. No default: a word
   * the component invents is a word the product cannot translate.
   *
   * Leave it out and no clear button is drawn - which is the right shape for a
   * field that filters as you type and is cleared by other means.
   */
  clearLabel?: string
  /**
   * The shortcut that focuses the field, as `['Mod', 'K']`. Shown at the right
   * of the field, and bound: pressing it focuses and selects, from anywhere
   * that is not already a field.
   */
  shortcut?: string[]
  ref?: Ref<HTMLInputElement>
}

export function SearchField({
  value,
  onValueChange,
  clearLabel,
  shortcut,
  className,
  ref,
  ...props
}: SearchFieldProps) {
  const own = useRef<HTMLInputElement>(null)

  const setRefs = useCallback(
    (element: HTMLInputElement | null) => {
      own.current = element
      if (typeof ref === 'function') ref(element)
      else if (ref) ref.current = element
    },
    [ref],
  )

  // Focus and select, so the shortcut replaces a stale query rather than
  // appending to it. Not while someone is typing elsewhere - that is
  // `useShortcut`'s default, and it is the half of this people forget.
  const focusAndSelect = useCallback(() => {
    own.current?.focus()
    own.current?.select()
  }, [])
  useShortcut(shortcut ?? [], focusAndSelect, { enabled: shortcut !== undefined })

  const showClear = clearLabel !== undefined && value !== ''

  return (
    <div className={cn('relative', className)}>
      <MagnifierIcon />

      <input
        ref={setRefs}
        type="search"
        value={value}
        onChange={(event) => onValueChange(event.target.value)}
        className={cn(
          fieldClasses,
          'h-9 pl-8',
          // Room on the right for whatever sits there, and none when nothing
          // does - a field with a permanent gap looks broken.
          showClear && 'pr-8',
          !showClear && shortcut && 'pr-14',
          // The browser's own clear affordance, in the operating system's
          // chrome. Ours is below.
          '[&::-webkit-search-cancel-button]:appearance-none',
        )}
        {...props}
      />

      {showClear && (
        <button
          type="button"
          aria-label={clearLabel}
          onClick={() => {
            onValueChange('')
            own.current?.focus()
          }}
          className={cn(
            'absolute right-1.5 top-1/2 grid size-6 -translate-y-1/2 place-items-center',
            'rounded-sm text-faint transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <CrossIcon />
        </button>
      )}

      {!showClear && shortcut && (
        // Decorative: the shortcut works whether or not it is read out, and a
        // screen reader announcing "Control K" inside a search box is noise.
        <Kbd
          keys={shortcut}
          aria-hidden
          className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2"
        />
      )}
    </div>
  )
}

function MagnifierIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      aria-hidden
      className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-faint"
    >
      <circle cx="7" cy="7" r="4.5" />
      <path d="M10.5 10.5L14 14" strokeLinecap="round" />
    </svg>
  )
}

function CrossIcon() {
  return (
    <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
    </svg>
  )
}

import { Select as Base } from '@base-ui/react/select'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Select.
 *
 * The component the oldest rule in the line is about. A native `<select>`
 * cannot be dressed: the browser draws its popup itself, in the operating
 * system's chrome, and no CSS reaches inside. One native dropdown on a screen
 * of the product's own controls reads as a foreign object, and on Windows it
 * reads as a foreign object from 1998.
 *
 * So this renders `<button role="combobox">` and a portalled list of
 * `role="option"` - zero native elements, which is asserted in the test,
 * because it is the entire reason the component exists.
 *
 * What that costs is everything the browser was doing for free: the keyboard,
 * type-ahead, the announcement of the selected value, the scroll into view,
 * and on a phone the whole native picker. Base UI does all of it, which is
 * the only reason this trade is worth making - a hand-rolled dropdown is how
 * a product ships a control that a screen reader cannot see.
 *
 * The trigger wears Input's `fieldClasses`, imported rather than copied. A
 * select and a text field sit next to each other in every form there has ever
 * been, and two class lists that started the same drift within a release.
 *
 * `multiple` is a prop on the Root: it changes what `value` means - an array
 * rather than a single value - so it belongs where the value lives and not on
 * the trigger.
 */

export const selectTriggerVariants = cva([fieldClasses, 'flex items-center justify-between gap-2'], {
  variants: {
    size: {
      sm: 'h-8 text-xs',
      md: 'h-9',
      lg: 'h-10 text-base',
    },
  },
  defaultVariants: { size: 'md' },
})

export const selectPopupVariants = cva(
  [
    'max-h-[min(24rem,var(--available-height))] overflow-y-auto',
    'rounded-md border border-line bg-raise p-1 text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        // The popup matches the trigger's width by default, which is what a
        // dropdown should do; the sizes are a floor for a narrow one.
        sm: 'min-w-[max(8rem,var(--anchor-width))]',
        md: 'min-w-[max(10rem,var(--anchor-width))]',
        lg: 'min-w-[max(14rem,var(--anchor-width))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** One option. */
export const selectItemVariants = cva([
  'relative flex cursor-pointer select-none items-center gap-2 rounded-sm py-1.5 pl-2 pr-7 text-sm',
  'outline-none transition-colors',
  // Base UI marks the item under the pointer or the keyboard the same way,
  // so one rule covers both and they cannot disagree.
  'data-[highlighted]:bg-soft data-[highlighted]:text-text',
  'data-[selected]:text-text',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
  '[&_svg]:size-3.5 [&_svg]:shrink-0',
])

/** The root. `multiple` turns `value` into an array; otherwise controlled with
 * `value` and `onValueChange`, or left to manage itself. */
export const Select = Base.Root

/** What the trigger shows: the selected item's label, and the `placeholder`
 * the product gives it until there is one.
 *
 * Two traps, both Base UI's and both quiet. Its `children` is a *function* of
 * the value, not a node - passing a node pins the trigger to that node
 * forever and the selection never appears, so the placeholder goes in
 * `placeholder`. And what it shows is the raw value, `plum` rather than
 * `Plum`, unless the root is given an `items` map to look the label up in. */
export const SelectValue = Base.Value

/** The chevron, or whatever the product puts there. Marked decorative by Base
 * UI, since the button is already named by its value. */
export const SelectIcon = Base.Icon

/** A labelled group of options. */
export const SelectGroup = Base.Group

/** The text of an option, which is what the trigger echoes when it is chosen. */
export const SelectItemText = Base.ItemText

/** The tick, drawn only on the chosen option. */
export const SelectItemIndicator = Base.ItemIndicator

export interface SelectTriggerProps
  extends Base.Trigger.Props,
    VariantProps<typeof selectTriggerVariants> {}

/** The control. A `<button role="combobox">` - never a `<select>`. */
export function SelectTrigger({ size, className, ...props }: SelectTriggerProps) {
  return <Base.Trigger className={cn(selectTriggerVariants({ size }), className)} {...props} />
}

export interface SelectPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof selectPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body, which keeps the list
   * from being clipped by a form with `overflow: hidden`. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the trigger.
 *
 * `alignItemWithTrigger` is off: Base UI's default lifts the popup so the
 * selected option sits over the button, which is the native macOS behaviour
 * and is disorienting in a web form - the list jumps to a different place
 * depending on what is already chosen. */
export function SelectPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: SelectPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignItemWithTrigger={false}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(selectPopupVariants({ size }), className)} {...props}>
          <Base.List>{children}</Base.List>
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** An option. */
export function SelectItem({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(selectItemVariants(), className)} {...props} />
}

/** The caption above a group. */
export function SelectGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

/** A line between groups of options. */
export function SelectSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

import { useEffect } from 'react'

/*
 * Shortcut.
 *
 * Two things every product writes and half of them get subtly wrong: deciding
 * whether a keystroke is the shortcut, and deciding whether now is a moment to
 * act on it.
 *
 * The second is the one that bites. A shortcut that fires while someone is
 * typing in a field is a bug nobody can describe afterwards - `Mod+K` inside a
 * text editor means "delete to end of line", and a palette that opens on top
 * of it looks like the application misheard. So a keystroke aimed at an input,
 * a textarea or anything `contenteditable` belongs to that thing, always.
 *
 * A shortcut is written the way it is read: `['Mod', 'K']`. `Mod` is command
 * on Apple platforms and control everywhere else, which is the same rule Kbd
 * draws it by, so what is bound and what is shown cannot disagree.
 */

/** Whether the event landed somewhere that owns its own keys. */
export function isTypingTarget(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null
  if (!element) return false
  const tag = element.tagName
  // Coerced: `isContentEditable` is computed from layout, and an engine that
  // does not lay out - jsdom, and any server render - leaves it `undefined`
  // rather than `false`. Truthiness is enough for the branch below, but a
  // function that says it returns a boolean has to.
  return tag === 'INPUT' || tag === 'TEXTAREA' || Boolean(element.isContentEditable)
}

/** Does this event match the shortcut? Exported because a product sometimes
 * has to ask the question inside a handler it already owns. */
export function matchesShortcut(event: KeyboardEvent, shortcut: string[]): boolean {
  const wants = new Set(shortcut.map((key) => key.toLowerCase()))
  const mod = wants.delete('mod')
  const shift = wants.delete('shift')
  const alt = wants.delete('alt')
  const [key] = [...wants]
  if (key === undefined) return false

  // An exact match on every modifier, in both directions: `Mod+K` must not
  // fire on `Mod+Shift+K`, which is usually a different command entirely.
  if (mod !== (event.metaKey || event.ctrlKey)) return false
  if (shift !== event.shiftKey) return false
  if (alt !== event.altKey) return false
  return event.key.toLowerCase() === key
}

export interface UseShortcutOptions {
  /** Bind it at all. For a shortcut that only exists on some screens. */
  enabled?: boolean
  /**
   * Fire even while someone is typing in a field.
   *
   * Off by default, and the default is the point. Turn it on for a shortcut
   * that belongs to the field itself - `Escape` closing the box it is typed
   * in - and never for one that takes the person somewhere else.
   */
  whileTyping?: boolean
}

/**
 * Run something when a shortcut is pressed.
 *
 * The handler is read from a ref, so a caller that writes it inline does not
 * rebind the listener on every render - which is how these end up firing twice.
 */
export function useShortcut(
  shortcut: string[],
  onPress: (event: KeyboardEvent) => void,
  { enabled = true, whileTyping = false }: UseShortcutOptions = {},
): void {
  useEffect(() => {
    if (!enabled) return

    const onKeyDown = (event: KeyboardEvent) => {
      if (!whileTyping && isTypingTarget(event.target)) return
      if (!matchesShortcut(event, shortcut)) return
      event.preventDefault()
      onPress(event)
    }

    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
    // `shortcut` is an array literal at most call sites, so it is joined
    // rather than compared by identity: otherwise every render rebinds.
  }, [shortcut.join('+'), onPress, enabled, whileTyping]) // eslint-disable-line react-hooks/exhaustive-deps
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Spinner.
 *
 * Something is happening and the answer has not arrived. It carries no text of
 * its own - what is loading is the product's word, not the system's - but it
 * does have to say *something* to a screen reader, or a page that is busy is
 * silently identical to a page that is empty.
 *
 * Under `prefers-reduced-motion` the theme stops the animation. That is not a
 * detail: for some readers a spinning thing is not decoration but a symptom.
 * A stopped spinner still says "busy" through `role`, which is the part that
 * carried the meaning all along.
 */
export const spinnerVariants = cva('inline-block animate-spin rounded-full border-2 border-current', {
  variants: {
    size: {
      sm: 'size-3.5 border-[1.5px]',
      md: 'size-4',
      lg: 'size-6',
    },
    tone: {
      /* Follows the text it sits in. */
      current: 'text-current',
      dim: 'text-dim',
      accent: 'text-accent',
    },
  },
  defaultVariants: { size: 'md', tone: 'current' },
})

export interface SpinnerProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof spinnerVariants> {
  /** What is being waited for, for a screen reader. The product's word. */
  label?: string
}

export function Spinner({ size, tone, label, className, ...props }: SpinnerProps) {
  return (
    <span role="status" aria-live="polite" className={cn('inline-flex items-center gap-2', className)} {...props}>
      <span
        // The gap in the ring is what makes the rotation visible.
        className={cn(spinnerVariants({ size, tone }), 'border-r-transparent')}
        aria-hidden
      />
      {label && <span className="sr-only">{label}</span>}
    </span>
  )
}

import { useCallback, useLayoutEffect, useRef, type Ref, type TextareaHTMLAttributes } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Textarea.
 *
 * A multi-line field that can grow with what is typed into it, which is the
 * only interesting part: a fixed box makes someone scroll inside a scroll,
 * and a box that grows without limit pushes the button they are trying to
 * reach off the screen. `autoResize` grows it; `maxRows` says when to stop
 * and let it scroll after all.
 *
 * The measurement is the usual trick and worth stating: height is reset to
 * `auto` before reading `scrollHeight`, because a box already tall enough
 * reports its own height and never shrinks back.
 */
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  ref?: Ref<HTMLTextAreaElement>
  /** Grow to fit the content instead of scrolling. */
  autoResize?: boolean
  /** Stop growing here, in lines, and scroll instead. */
  maxRows?: number
}

export function Textarea({
  className,
  ref,
  autoResize = false,
  maxRows,
  onChange,
  ...props
}: TextareaProps) {
  const own = useRef<HTMLTextAreaElement>(null)

  const resize = useCallback(() => {
    const element = own.current
    if (!element || !autoResize) return

    // Reset first: a box that is already tall enough reports its own height as
    // `scrollHeight` and would never shrink again.
    element.style.height = 'auto'

    const styles = getComputedStyle(element)
    const lineHeight = Number.parseFloat(styles.lineHeight) || 0
    const vertical =
      Number.parseFloat(styles.paddingTop) +
      Number.parseFloat(styles.paddingBottom) +
      Number.parseFloat(styles.borderTopWidth) +
      Number.parseFloat(styles.borderBottomWidth)

    const wanted = element.scrollHeight
    const ceiling = maxRows && lineHeight ? maxRows * lineHeight + vertical : Infinity

    element.style.height = `${Math.min(wanted, ceiling)}px`
    element.style.overflowY = wanted > ceiling ? 'auto' : 'hidden'
  }, [autoResize, maxRows])

  // Before paint, so the field never appears at the wrong height and then
  // jumps - including on the first render, when it may already have a value.
  useLayoutEffect(resize, [resize, props.value, props.defaultValue])

  return (
    <textarea
      ref={(element) => {
        own.current = element
        if (typeof ref === 'function') ref(element)
        else if (ref) ref.current = element
      }}
      onChange={(event) => {
        resize()
        onChange?.(event)
      }}
      className={cn(fieldClasses, autoResize ? 'resize-none' : 'resize-y', className)}
      {...props}
    />
  )
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Truncate.
 *
 * Text that does not fit, cut with an ellipsis - and, importantly, still
 * readable in full: the element carries its own text as a `title`, so hovering
 * shows what was cut. Every product wrote the one-line version of this and
 * none of them remembered the title.
 *
 * `lines` truncates after that many instead of one, which needs a different
 * mechanism (`line-clamp`) rather than a different value.
 */
export interface TruncateProps extends HTMLAttributes<HTMLSpanElement> {
  /** The text. A string, because the component has to be able to put it in a
   * `title` - arbitrary children could not be. */
  children: string
  /** Cut after this many lines. One by default. */
  lines?: number
  /** Say what the full text is on hover. On by default; turn it off where the
   * text is already visible elsewhere, or the tooltip is noise. */
  title?: string | undefined
}

export function Truncate({ children, lines = 1, className, title, ...props }: TruncateProps) {
  return (
    <span
      // The browser shows this only when the text is actually cut, so it costs
      // nothing when everything fits.
      title={title ?? children}
      className={cn(
        lines === 1 ? 'block truncate' : 'block overflow-hidden',
        className,
      )}
      style={
        lines > 1
          ? { display: '-webkit-box', WebkitLineClamp: lines, WebkitBoxOrient: 'vertical' }
          : undefined
      }
      {...props}
    >
      {children}
    </span>
  )
}
